const yaml = require('yaml');

const fs = require('node:fs');
const path = require('node:path');

const PREFIX =
  '# AUTOGENERATED FILE - DO NOT EDIT MANUALLY\n# ONLY EDIT .github/workflows/pipeline-segment-electron-build.yml\n\n';

const base = path.resolve(__dirname, '../.github/workflows/pipeline-segment-electron-build.yml');
const target = path.resolve(__dirname, '../.github/workflows/pipeline-segment-electron-publish.yml');

const baseContents = fs.readFileSync(base, 'utf-8');

const parsedBase = yaml.parse(baseContents);
parsedBase.name = 'Pipeline Segment - Electron Publish';
parsedBase.jobs.build.permissions = {
  'artifact-metadata': 'write',
  attestations: 'write',
  contents: 'read',
  'id-token': 'write'
};

// yaml.stringify drops comments, so re-attach the zizmor ignore comment from
// the base workflow's container line to the generated output.
const generated = (PREFIX + yaml.stringify(parsedBase)).replace(
  /^(\s*container: .*build-container.*)$/m,
  '$1 # zizmor: ignore[unpinned-images] caller passes a ghcr.io/electron/build image tagged by content sha'
);

if (process.argv.includes('--check')) {
  if (fs.readFileSync(target, 'utf-8') !== generated) {
    console.error(`${target} is out of date`);
    console.error('Please run "copy-pipeline-segment-publish.js" to update it');
    process.exit(1);
  }
} else {
  fs.writeFileSync(target, generated);
}
